int get_pppox_l2tp_options(struct socket *sock, int level, int optname,
                           char __user *optval, int __user *optlen)
{
    struct sock *sk = sock->sk;
    struct l2tp_tunnel *tunnel;
    struct l2tp_session *session;
    int val, len;

    if (level != SOL_PPPOL2TP)
        return -EINVAL;

    if (optname != PPPOX_OPT_CAUSE_CODE && optname != PPPOX_OPT_CONN_ID)
        return -EINVAL;

    if (!sock->sk->sk_user_data)
        return -ENOTCONN;

    session = sock->sk->sk_user_data;

    tunnel = session->tunnel;
    if (!tunnel)
        return -ENOTCONN;

    if (optname == PPPOX_OPT_CAUSE_CODE) {
        val = session->session_id;
        len = sizeof(val);
    } else {
        val = session->tunnel->tid;
        len = sizeof(val);
    }

    if (put_user(len, optlen))
        return -EFAULT;

    if (copy_to_user(optval, &val, len))
        return -EFAULT;

    return 0;
}

int get_pppol2tp_sockopt(struct socket *sock, int level, int optname, char __user *optval, int __user *optlen)
{
    int ret = 0;
    int len;
    struct sock *sk = sock->sk;
    struct pppol2tp_session *session;
    struct pppol2tp_tunnel *tunnel = NULL;

    if (level != SOL_PPPOL2TP)
        return -EINVAL;

    if (get_user(len, optlen))
        return -EFAULT;

    if (len < 0)
        return -EINVAL;

    if (sk->sk_state != PPPOX_CONNECTED)
        return -ENOTCONN;

    session = pppol2tp_get_session(sk);
    if (!session)
        return -ENOENT;

    tunnel = session->tunnel;
    if (!tunnel)
        return -ENOENT;

    switch (optname) {
    case PPPOE_OPT_TUNNEL:
        if (len < sizeof(*tunnel))
            return -EINVAL;
        len = sizeof(*tunnel);
        if (copy_to_user(optval, tunnel, len))
            return -EFAULT;
        break;
    case PPPOE_OPT_SESSION:
        if (len < sizeof(*session))
            return -EINVAL;
        len = sizeof(*session);
        if (copy_to_user(optval, session, len))
            return -EFAULT;
        break;
    default:
        return -ENOPROTOOPT;
    }

    if (put_user(len, optlen))
        return -EFAULT;

    return ret;
}

int sock_ppl2tp_getsockopt(struct socket *sock, int level, int optname, char __user *optval, int __user *optlen) {
    int ret = -EINVAL;
    int len;
    struct sock *sk = sock->sk;
    struct pppl2tp_session *s;

    if (level != SOL_PPPOL2TP)
        return -EOPNOTSUPP;

    if (get_user(len, optlen))
        return -EFAULT;

    if (len < 0)
        return -EINVAL;

    if (!sock->sk->sk_state)
        return -ENOTCONN;

    s = (struct pppl2tp_session *)sk->sk_user_data;

    if (!s)
        return -ENOPROTOOPT;

    if (s->session_id) {
        if (optname == PPPOL2TP_SO_RECVTIMEO || optname == PPPOL2TP_SO_SNDTIMEO) {
            long timeout = sock->sk->sk_rcvtimeo;
            if (optname == PPPOL2TP_SO_SNDTIMEO)
                timeout = sock->sk->sk_sndtimeo;

            if (put_user(timeout, (long __user *)optval) ||
                put_user(sizeof(long), optlen))
                return -EFAULT;

            ret = 0;
        } else {
            return -ENOPROTOOPT;
        }
    } else {
        return -ENOPROTOOPT;
    }

    return ret;
}

int get_pppol2tp_sock_options(struct socket *sock, int level, int optname, char __user *optval, int __user *optlen)
{
    int ret = 0;
    struct sock *sk = sock->sk;
    struct pppol2tp_session *session;
    int optlen_val;

    if (level != SOL_PPPOL2TP)
        return -EINVAL;

    if (get_user(optlen_val, optlen))
        return -EFAULT;

    if (optlen_val < 0)
        return -EINVAL;

    if (!sk || !sk->sk_state || !sk->sk_state_connected)
        return -ENOTCONN;

    session = get_session_from_sock(sk);
    if (!session)
        return -ENOENT;

    if (optname == PPPOLOPT_TUNNEL) {
        if (session->tunnel_id == 0)
            return -ENOENT;

        ret = copy_to_user(optval, &session->tunnel_id, sizeof(session->tunnel_id));
        if (ret)
            return -EFAULT;

        put_user(sizeof(session->tunnel_id), optlen);
    } else if (optname == PPPOLOPT_SESSION) {
        if (session->session_id == 0)
            return -ENOENT;

        ret = copy_to_user(optval, &session->session_id, sizeof(session->session_id));
        if (ret)
            return -EFAULT;

        put_user(sizeof(session->session_id), optlen);
    } else {
        return -ENOPROTOOPT;
    }

    return ret;
}

